export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <header className={`navbar ${scrolled ? 'navbar--scrolled' : ''}`} role="banner">
      <div className="navbar__inner">
        <a href="/" className="navbar__logo" aria-label="Basecamp — Home">
          <span className="navbar__logo-icon-3d" aria-hidden="true">
            <img src={basecampLogo3D} alt="" className="navbar__logo-3d-img" />
          </span>
          <BasecampLogo />
        </a>

        <nav className="navbar__nav" role="navigation" aria-label="Main navigation">
          <ul className="navbar__links">
            <li>
              <a href="#features" className="navbar__link">
                Product <ChevronDown />
              </a>
            </li>
            <li>
              <a href="#pricing" className="navbar__link">Pricing</a>
            </li>
            <li>
              <a href="#testimonial" className="navbar__link">Customers</a>
            </li>
            <li>
              <a href="#" className="navbar__link">
                Resources <ChevronDown />
              </a>
            </li>
          </ul>

          <div className="navbar__actions">
            <ThemeToggle />
            <button className="navbar__login" type="button">
              Log in
            </button>
            <Button variant="primary" size="sm" id="nav-cta-start-trial">
              Start free trial
            </Button>
          </div>
        </nav>
      </div>
    </header>
  );
}
